 const next=agenda.filter(i=>['invited','confirmed','reschedule_requested'].includes(i.state)&&date(i.scheduled_at)&&date(i.scheduled_at).getTime()+(Number(i.duration_minutes)||30)*60000>=now).sort((a,b)=>date(a.scheduled_at)-date(b.scheduled_at));
 return {apps,counts,unseen:apps.filter(c=>c.visualizada!==true&&!['canceladas','reprovadas'].includes(stage(c))).length,next,awaitingConfirmation:next.filter(i=>i.state==='invited').length,reschedule:next.filter(i=>i.state==='reschedule_requested').length};
