 next.nome_fantasia=next.nomeFantasia;next.razao_social=next.razaoSocial;next.email_corporativo=next.emailCorporativo;next.telefone=next.telefoneEmpresa;
 if(Object.keys(object(company.endereco)).length){const address=Object.assign({},object(company.endereco),{cidade:next.cidade,uf:next.uf});next.endereco=typeof company.endereco==='string'?JSON.stringify(address):address;}
 profile.nome=next.nomeFantasia;profile.cidade=next.cidade;profile.uf=next.uf;profile.site=v.site||'';profile.atualizadoEm=now;next.site=profile.site;
 for(const key of ['segmento','porte','sobre','logo'])if(v[key]){profile[key]=v[key];if(!next[key])next[key]=v[key];}
